"""Render the production / Tableau evidence model as one portable HTML file.

Usage: python scripts/tableau/render_artifact.py [model.json] [output.html]
The renderer never connects to Salesforce and embeds no record-level data.
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path


