def render(model_path: Path, output_path: Path) -> None:
    model = json.loads(model_path.read_text(encoding="utf-8-sig"))
    for required in ("scope", "objects", "relations"):
        if required not in model:
            raise ValueError(f"Missing model section: {required}")
    encoded = json.dumps(model, ensure_ascii=False, separators=(",", ":"))
    encoded = encoded.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(TEMPLATE.replace("__MODEL_JSON__", encoded), encoding="utf-8")
    print(f"Rendered {output_path} ({output_path.stat().st_size:,} bytes)")
    print(f"Embedded {len(model['objects'])} objects and {len(model['relations'])} schema reference edges.")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("model", nargs="?", type=Path, default=Path(".local/tableau-production/model.json"))
    parser.add_argument("output", nargs="?", type=Path, default=Path(".lavish/tableau-production-relationships.html"))
    args = parser.parse_args()
    render(args.model, args.output)
